// 酒馆资产批量清理中心 - GitHub CDN 实时热更新加载器 (sisjzknxhnsnejxn-cmyk/st-batch-cleaner)
(() => {
  const BTN_NAME = '🧹 打开批量清理中心';
  let openFn = null, pendingOpen = false, loadFailed = false, isLoading = false;
  window.__ST_BATCH_CLEANER_REGISTER_OPEN__ = (fn) => {
    openFn = fn; loadFailed = false; isLoading = false;
    if (pendingOpen) { pendingOpen = false; fn(); }
  };
  function handleTrigger() {
    if (typeof openFn === 'function') { openFn(); return; }
    if (typeof window.__ST_BATCH_CLEANER_OPEN__ === 'function') { window.__ST_BATCH_CLEANER_OPEN__(); return; }
    pendingOpen = true;
    if (loadFailed && !isLoading) {
      if (typeof toastr !== 'undefined') toastr.info('正在重新从云端加载批量清理中心...', '', { timeOut: 2000 });
      loadRemoteBundle();
      return;
    }
    if (typeof toastr !== 'undefined') toastr.info('正在从云端加载批量清理中心，完成后将自动打开...', '', { timeOut: 2000 });
  }
  try { appendInexistentScriptButtons([{ name: BTN_NAME, visible: true }]); } catch (_) {}
  try { eventOn(getButtonEvent(BTN_NAME), () => handleTrigger()); } catch (_) {}
  async function loadRemoteBundle() {
    if (isLoading || typeof openFn === 'function') return;
    isLoading = true; loadFailed = false;
    const repo = 'sisjzknxhnsnejxn-cmyk/st-batch-cleaner';
    const file = 'dist/st-batch-cleaner/index.js';
    const refs = [];
    try {
      const ctrl = new AbortController(), tm = setTimeout(() => ctrl.abort(), 1800);
      const res = await fetch('https://api.github.com/repos/' + repo + '/commits/main', { cache: 'no-store', signal: ctrl.signal });
      clearTimeout(tm);
      if (res.ok) { const d = await res.json(); if (d && d.sha) refs.push(d.sha); }
    } catch (_) {}
    refs.push('main');
    const urls = [], bust = Date.now();
    for (const r of refs) {
      for (const h of ['testingcf.jsdelivr.net', 'fastly.jsdelivr.net', 'cdn.jsdelivr.net', 'gcore.jsdelivr.net']) {
        urls.push('https://' + h + '/gh/' + repo + '@' + r + '/' + file + '?t=' + bust);
      }
    }
    urls.push('https://raw.githubusercontent.com/' + repo + '/main/' + file + '?t=' + bust);
    for (const u of urls) {
      const ctrl = new AbortController(), tm = setTimeout(() => ctrl.abort(), 6500);
      try {
        const res = await fetch(u, { cache: 'no-store', signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        const code = await res.text();
        if (!code || code.length < 100) throw new Error('Empty');
        clearTimeout(tm);
        new Function(code)();
        isLoading = false; loadFailed = false; return;
      } catch (e) { clearTimeout(tm); }
    }
    isLoading = false; loadFailed = true;
    if (typeof toastr !== 'undefined') toastr.error('云端脚本加载失败，再次点击「🧹 打开批量清理中心」可重试');
  }
  loadRemoteBundle();
})();
